-- Pago y entrega express: pgTAP transaccional, sin escritura remota.
begin;
create schema if not exists extensions;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(44);
insert into auth.users(id,email) values('10000000-0000-4000-8000-000000000001','evalia-quick-cashier@example.invalid');
insert into public.admin_profiles(user_id) values('10000000-0000-4000-8000-000000000001');
insert into public.models(id,name,size_label,price_dozen_bs) values('20000000-0000-4000-8000-000000000001','Modelo cobro express','Única',360.00);
update public.model_inventory set on_hand=48 where model_id='20000000-0000-4000-8000-000000000001'::uuid;
insert into public.customers(id,name,whatsapp) values('30000000-0000-4000-8000-000000000001','Comprador QA','0000000');
set local role authenticated;
set local request.jwt.claim.sub = '10000000-0000-4000-8000-000000000001';
select lives_ok($q$select public.create_evalia_order('30000000-0000-4000-8000-000000000001'::uuid,'[{"modelId":"20000000-0000-4000-8000-000000000001","dozens":1,"extraColorIds":[]}]'::jsonb,'71000000-0000-4000-8000-000000000001'::uuid)$q$,'pedido A confirmado');
select throws_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid),'pay','72000000-0000-4000-8000-000000000001'::uuid,null,false,false)$q$,'22023','Confirmaciones de cobro/entrega incompletas o inválidas','no declara dinero sin confirmar recepción');
select throws_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid),'deliver','72000000-0000-4000-8000-000000000002'::uuid,null,false,false)$q$,'22023','Confirmaciones de cobro/entrega incompletas o inválidas','no declara entrega sin confirmar retirada');
select throws_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid),'deliver','72000000-0000-4000-8000-000000000002'::uuid,null,false,true)$q$,'23514','No entregar sin pago total aprobado','bloquea entrega sin saldo pagado');
select lives_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid),'pay','72000000-0000-4000-8000-000000000001'::uuid,'Efectivo validado',true,false)$q$,'registrar pago total aprobado');
select is((select (public.get_evalia_order_finance((select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid))->>'approved')::numeric),360.00::numeric,'saldo abonado 360 exactos');
select is((select status from public.orders where id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid)),'active'::text,'pago adelantado no marca retirado');
select is((select on_hand from public.model_inventory where model_id='20000000-0000-4000-8000-000000000001'::uuid),48::integer,'pago sin entrega no reduce físico');
select lives_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid),'pay','72000000-0000-4000-8000-000000000001'::uuid,'Efectivo validado',true,false)$q$,'reintento pago total no duplica');
select is((select count(*)::integer from public.payment_reports where order_id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid)),1::integer,'un solo reporte pago');
select is((select count(*)::integer from public.payment_reviews pr join public.payment_reports p on pr.report_id=p.id where p.order_id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid)),1::integer,'revisión de pago auditada una vez');
select throws_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid),'pay','72000000-0000-4000-8000-000000000001'::uuid,'Nota alterada',true,false)$q$,'23505','Reintento express con datos distintos','rechaza request reutilizado');
select lives_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid),'deliver','72000000-0000-4000-8000-000000000002'::uuid,null,false,true)$q$,'entrega completa posterior al pago');
select is((select status from public.orders where id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid)),'completed'::text,'retiro cierra pedido previamente pagado');
select is((select on_hand from public.model_inventory where model_id='20000000-0000-4000-8000-000000000001'::uuid),36::integer,'entrega descuenta inventario una sola vez');
select lives_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid),'deliver','72000000-0000-4000-8000-000000000002'::uuid,null,false,true)$q$,'reintento entrega ya cerrada responde idempotente');
select is((select count(*)::integer from public.deliveries where order_id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000001'::uuid)),1::integer,'una única entrega A');
select lives_ok($q$select public.create_evalia_order('30000000-0000-4000-8000-000000000001'::uuid,'[{"modelId":"20000000-0000-4000-8000-000000000001","dozens":1,"extraColorIds":[]}]'::jsonb,'71000000-0000-4000-8000-000000000002'::uuid)$q$,'pedido B confirmado');
select lives_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000002'::uuid),'pay_deliver','72000000-0000-4000-8000-000000000003'::uuid,'Pago y recogida en feria',true,true)$q$,'cobro y retiro atómicos');
select is((select status from public.orders where id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000002'::uuid)),'completed'::text,'venta al contado completa');
select is((select count(*)::integer from public.payment_reports where order_id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000002'::uuid) and status='approved'),1::integer,'solo un pago B aprobado');
select is((select (public.get_evalia_order_delivery((select id from public.orders where request_id='71000000-0000-4000-8000-000000000002'::uuid))->>'remaining')::integer),0::integer,'no quedan prendas B');
select is((select on_hand from public.model_inventory where model_id='20000000-0000-4000-8000-000000000001'::uuid),24::integer,'stock físico B descuenta una vez');
select lives_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000002'::uuid),'pay_deliver','72000000-0000-4000-8000-000000000003'::uuid,'Pago y recogida en feria',true,true)$q$,'reintento ambos no duplica');
select is((select count(*)::integer from public.order_quick_actions where order_id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000002'::uuid)),1::integer,'una sola auditoría rápida B');
select throws_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000002'::uuid),'pay_deliver','72000000-0000-4000-8000-000000000098'::uuid,null,true,true)$q$,'23514','Pedido inexistente o ya completado','cierre repetido con otro request se rechaza');
select lives_ok($q$select public.create_evalia_order('30000000-0000-4000-8000-000000000001'::uuid,'[{"modelId":"20000000-0000-4000-8000-000000000001","dozens":1,"extraColorIds":[]}]'::jsonb,'71000000-0000-4000-8000-000000000003'::uuid)$q$,'pedido C confirmado');
select lives_ok($q$select public.report_evalia_payment(null,(select id from public.orders where request_id='71000000-0000-4000-8000-000000000003'::uuid),50.00,'73000000-0000-4000-8000-000000000001'::uuid,'Cliente declaró depósito')$q$,'aviso pendiente del cliente');
select throws_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000003'::uuid),'pay','72000000-0000-4000-8000-000000000004'::uuid,null,true,false)$q$,'23514','Hay pagos aún sin revisar: verifícalos antes del cobro rápido','pago sin revisar bloquea atajo');
select is((select count(*)::integer from public.order_quick_actions where order_id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000003'::uuid)),0::integer,'no hay movimiento tras rechazo');
select lives_ok($q$select public.review_evalia_payment((select id from public.payment_reports where request_id='73000000-0000-4000-8000-000000000001'::uuid),'approve','73000000-0000-4000-8000-000000000002'::uuid,'Ingreso comprobado')$q$,'revisar abono real antes de cobro restante');
select lives_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000003'::uuid),'pay_deliver','72000000-0000-4000-8000-000000000004'::uuid,null,true,true)$q$,'cobro del saldo restante y entrega C');
select is((select (public.get_evalia_order_finance((select id from public.orders where request_id='71000000-0000-4000-8000-000000000003'::uuid))->>'approved')::numeric),360.00::numeric,'abona 50+310 sin duplicar');
select is((select paid_amount from public.order_quick_actions where order_id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000003'::uuid)),310.00::numeric,'atajo solo registra el saldo, no el total dos veces');
select is((select on_hand from public.model_inventory where model_id='20000000-0000-4000-8000-000000000001'::uuid),12::integer,'entrega C registra físico exacto');
select lives_ok($q$select public.create_evalia_order('30000000-0000-4000-8000-000000000001'::uuid,'[{"modelId":"20000000-0000-4000-8000-000000000001","dozens":1,"extraColorIds":[]}]'::jsonb,'71000000-0000-4000-8000-000000000004'::uuid)$q$,'pedido D pendiente para simular falta de físico');
reset role;
update public.model_inventory set on_hand=0 where model_id='20000000-0000-4000-8000-000000000001'::uuid;
set local role authenticated;
set local request.jwt.claim.sub = '10000000-0000-4000-8000-000000000001';
set local request.jwt.claim.sub = '10000000-0000-4000-8000-000000000099';
reset role;
select throws_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000004'::uuid),'pay_deliver','72000000-0000-4000-8000-000000000005'::uuid,null,true,true)$q$,'23514','El stock físico es insuficiente','falla la entrega y revierte el pago atómicamente');
select is((select count(*)::integer from public.payment_reports where order_id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000004'::uuid)),0::integer,'sin pago ficticio tras rollback físico');
select is((select status from public.orders where id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000004'::uuid)),'active'::text,'pedido D permanece activo tras fallo');
select is((select count(*)::integer from public.order_quick_actions where order_id=(select id from public.orders where request_id='71000000-0000-4000-8000-000000000004'::uuid)),0::integer,'sin auditoría express de operación fallida');
select throws_ok($q$select public.quick_evalia_checkout((select id from public.orders where request_id='71000000-0000-4000-8000-000000000004'::uuid),'pay','72000000-0000-4000-8000-000000000005'::uuid,null,true,false)$q$,'42501','Acceso administrativo requerido','no-admin no registra cobro express');
select ok((not has_function_privilege('anon','public.quick_evalia_checkout(uuid,text,uuid,text,boolean,boolean)','EXECUTE')),'anónimo no tiene ejecución');
select ok((has_function_privilege('authenticated','public.quick_evalia_checkout(uuid,text,uuid,text,boolean,boolean)','EXECUTE')),'administrador puede invocar vía authenticated');
select ok((not has_table_privilege('authenticated','public.order_quick_actions','INSERT')),'auditoría no permite escritura directa');
select * from finish();
rollback;
